import os
import shutil

backup_root = '/home/melwinabi/Ubuntu_Backup'
home = '/home/melwinabi'
MAX_FILE_SIZE = 80 * 1024 * 1024 # 80 MB limit to guarantee GitHub accepts it

# 1. SRM
srm_src = os.path.join(home, 'Downloads/srm')
srm_dst = os.path.join(backup_root, 'srm')
if os.path.exists(srm_src):
    shutil.copytree(srm_src, srm_dst, dirs_exist_ok=True)
    print("srm copied.")

# 2. Pictures
pics_src = os.path.join(home, 'Pictures')
pics_dst = os.path.join(backup_root, 'Pictures')
if os.path.exists(pics_src):
    shutil.copytree(pics_src, pics_dst, dirs_exist_ok=True)
    print("Pictures copied.")

# 3. Music & Videos (.gitkeep)
for media_folder in ['Music', 'Videos']:
    dst_dir = os.path.join(backup_root, media_folder)
    os.makedirs(dst_dir, exist_ok=True)
    src_dir = os.path.join(home, media_folder)
    has_files = False
    if os.path.exists(src_dir):
        for f in os.listdir(src_dir):
            sp = os.path.join(src_dir, f)
            if os.path.isfile(sp) and os.path.getsize(sp) < MAX_FILE_SIZE:
                shutil.copy2(sp, os.path.join(dst_dir, f))
                has_files = True
    if not has_files:
        with open(os.path.join(dst_dir, '.gitkeep'), 'w') as f:
            f.write('')
    print(f"{media_folder} processed.")

# 4. Downloads
dl_src = os.path.join(home, 'Downloads')
dl_dst = os.path.join(backup_root, 'Downloads')
os.makedirs(dl_dst, exist_ok=True)

skip_dl_dirs = {'srm', 'easyeda-pro', 'st-stm32cubeide_2.1.1_28236_20260312_0043_amd64.deb_bundle.sh (1)'}
skip_dl_exts = {'.deb', '.appimage', '.tar.gz', '.tgz'}

for item in os.listdir(dl_src):
    if item in skip_dl_dirs or item.startswith('.'):
        continue
    sp = os.path.join(dl_src, item)
    dp = os.path.join(dl_dst, item)

    if os.path.isdir(sp):
        # copy dir recursively if small
        shutil.copytree(sp, dp, dirs_exist_ok=True, 
                        ignore=shutil.ignore_patterns('*.deb', '*.AppImage', '*.tar.gz', 'node_modules'))
    elif os.path.isfile(sp):
        ext = os.path.splitext(item)[1].lower()
        if ext in skip_dl_exts:
            continue
        try:
            if os.path.getsize(sp) < MAX_FILE_SIZE:
                shutil.copy2(sp, dp)
        except:
            pass
print("Downloads copied.")

# 5. Documents
doc_src = os.path.join(home, 'Documents')
doc_dst = os.path.join(backup_root, 'Documents')
os.makedirs(doc_dst, exist_ok=True)

skip_doc_items = {'OneDrive', 'SOFTWARES', 'ACER_Windows.zip'}

for item in os.listdir(doc_src):
    if item in skip_doc_items or item.startswith('.'):
        continue
    sp = os.path.join(doc_src, item)
    dp = os.path.join(doc_dst, item)

    if os.path.isdir(sp):
        for root, dirs, files in os.walk(sp):
            # filter out unwanted dirs
            dirs[:] = [d for d in dirs if d not in {'node_modules', '.next', 'venv', '__pycache__', '.git'}]
            rel = os.path.relpath(root, sp)
            target_dir = os.path.join(dp, rel)
            os.makedirs(target_dir, exist_ok=True)
            for f in files:
                fpath = os.path.join(root, f)
                try:
                    if os.path.getsize(fpath) < MAX_FILE_SIZE:
                        shutil.copy2(fpath, os.path.join(target_dir, f))
                except:
                    pass
    elif os.path.isfile(sp):
        try:
            if os.path.getsize(sp) < MAX_FILE_SIZE:
                shutil.copy2(sp, dp)
        except:
            pass

print("Documents copied.")
